import {readJSON,readContext,saveJSON,digest,isCLI} from './research-common.mjs';
import {base,hash} from './research-un-population-followup.mjs';
export function assess1960(){
 const matrix=readJSON('research/completion-01/reports/completion.json'),rows=matrix.rows.filter(r=>r.snapshotYear===1960),extracted=readJSON('research/bulk-02/population/dyb1960-population-extracted.json');
 const reviews=['research/bulk-02/population/independent-review.json','research/completion-01/population/independent-review.json'].map(readJSON);
 const reviewed=reviews.flatMap(r=>r.rows.map(x=>{const f=x.approvedMappedFields,slot=f&&rows.find(r=>r.entityId===f.entityId);return {observationId:x.observationId,decision:x.decision,reason:x.reason,entityId:f?.entityId,value:f?.value,observationDate:f?.observationDate,currentSlot:slot?.categories['population-statistics'].status||'not-represented-in-configured-matrix'};}));
 const wppReview=readJSON('research/completion-02/population/historical-crosswalk.json').mappings.filter(m=>m.applicableSnapshotYears.includes(1960));
 const wpp=wppReview.map(m=>({entityId:m.atlasEntityId,confidence:m.confidence,scopeRationale:m.scopeRationale,currentSlot:rows.find(r=>r.entityId===m.atlasEntityId)?.categories['population-statistics'].status||'not-represented'}));
 const safe=reviewed.filter(r=>r.decision==='source-and-mapping-approved'&&!['supported','not-represented-in-configured-matrix'].includes(r.currentSlot));
 const out={source:'Complete cached UN Demographic Yearbook 1960 Table 4 plus existing source-bound Table 6 review; cached WPP/OWID historical-territory crosswalk',tableRows:extracted.records.length,diagnosticNumericRows:extracted.records.filter(r=>r.candidateValue!==null).length,representedDossiers:rows.length,alreadySupported:rows.filter(r=>r.categories['population-statistics'].status==='supported').length,remaining:rows.filter(r=>r.categories['population-statistics'].status!=='supported').length,previouslySourceReviewed:reviewed.length,safeNewSlots:safe.length,safe,reviewed,wppReviewedMappings:wpp.length,wpp,unreviewedRows:extracted.records.filter(r=>!reviewed.some(x=>x.observationId===r.id)).map(r=>({id:r.id,label:r.rawTerritoryLabel,raw:r.rawValue,value:r.value,diagnosticValue:r.candidateValue,issues:r.reviewIssues,decision:'held-original-source-or-territorial-review-required'})),policy:'Existing independent review receipts are reused. Diagnostic OCR is never production evidence. No current-border series receives a new historical crosswalk merely by name matching. Previously held France/FRG/Australia/US/South Africa/Japan scope cases remain held. This exhausts existing AUTOMATICALLY APPROVED yield, not all possible historical research.'};
 saveJSON(base+'/1960-yield.json',out);return out;
}
export function compatibleDensity(population,area){
 return population.entityId===area.entityId&&population.scope.relationship==='same'&&area.scope.relationship==='same'&&population.scope.id===area.scope.id&&population.scope.description===area.scope.description&&digest(population.temporal)===digest(area.temporal)&&population.unit==='persons'&&['square miles','km2'].includes(area.unit)&&population.value>0&&area.value>0&&!/non.native|non.indigenous|excludes military|excludes.*armed|overseas|not polygon/i.test(population.scope.description);
}
export function assessDensity(){
 const store=readJSON('data/comprehensive-dossiers.json'),matrix=readJSON('research/completion-01/reports/completion.json'),claims=store.packages.flatMap(p=>p.claims),pop=claims.filter(c=>c.category==='population-statistics'),area=claims.filter(c=>c.category==='area-statistics');
 const pairs=[];for(const p of pop)for(const a of area)if(compatibleDensity(p,a)){
  const slots=matrix.rows.filter(r=>r.entityId===p.entityId&&r.categories['population-statistics'].records.includes(p.id)&&r.categories['area-statistics'].records.includes(a.id)&&r.categories.density.status!=='supported');
  if(slots.length)pairs.push({populationId:p.id,areaId:a.id,entityId:p.entityId,population:p.value,area:a.value,areaUnit:a.unit,temporal:p.temporal,scope:p.scope,slots:slots.map(r=>r.snapshotYear)});
 }
 const mapped=area.filter(a=>a.id.startsWith('mapped-area'));
 const out={populationClaims:pop.length,areaClaims:area.length,mappedAreaClaims:mapped.length,mappedPairsExplicitlyScopeCertified:pairs.filter(p=>p.areaId.startsWith('mapped-area')).length,sameSourceSameScopeSameDatePairs:pairs.length,newSafeDensitySlots:pairs.reduce((n,p)=>n+p.slots.length,0),pairs,policy:'Equal historical entity alone is insufficient. Exact certified scope ID, description and actual observation date must coincide. Population present/de-jure/census geography is not equated with atlas mapped geometry. Explicit same-source contemporary statistical-area pairs remain usable, with source input IDs, date and unit conversion retained.'};
 saveJSON(base+'/density-yield.json',out);return out;
}
export function buildDensity(){
 const r=assessDensity(),store=readJSON('data/comprehensive-dossiers.json'),original=store.packages.flatMap(p=>p.claims);
 const claims=r.pairs.map(x=>{const p=original.find(c=>c.id===x.populationId),a=original.find(c=>c.id===x.areaId),factor=x.areaUnit==='square miles'?2.589988110336:1;return {id:'compatible-density-'+digest([p.id,a.id,p.value,a.value,factor]).slice(0,24),entityId:x.entityId,category:'density',value:Number((p.value/(a.value*factor)).toPrecision(3)),unit:'persons/km2',metric:'Density (derived from compatible published population and area)',temporal:{...p.temporal},scope:{...p.scope},sourceIds:[...new Set([...p.sourceIds,...a.sourceIds])],evidence:[...p.evidence,...a.evidence].map(e=>({...e,interpretation:'derived',note:e.note+` Density derivation uses accepted population ${p.id} and area ${a.id}; population / (area × ${factor}) = persons per km2; rounded to three significant digits.`})),status:'supported',risks:[],qualifications:[...new Set([...p.qualifications,...a.qualifications]),'Derived from identical statistical scope and dated table inputs. Not density computed from the atlas polygon; no new census measurement or observation date is invented.','Three significant digits; 1 international square mile = 2.589988110336 square kilometres.'],origin:{kind:'bulk-candidate',reference:`Deterministic same-source/same-scope/same-date derivation; input population ${p.id}, area ${a.id}; factor ${factor}`,sourceIdentifier:p.id+' / '+a.id}};});
 const cohort={id:'completion03-compatible-statistical-density',worker:'same-scope-density-arithmetic',sources:[],claims};
 saveJSON(base+'/density-intake/cohort.json',cohort);saveJSON(base+'/density-intake/certificate.json',{cohortHash:digest(cohort),reviewer:'/root deterministic scope/date/input provenance review',bodyReviewed:true,acceptedClaimIds:claims.map(c=>c.id),inputBindings:[{path:'scripts/research-un-population-assessment.mjs',sha256:hash('scripts/research-un-population-assessment.mjs')},{path:base+'/density-yield.json',sha256:hash(base+'/density-yield.json')}],rationale:'Exact matching pre-existing certified statistical scope identifiers, descriptions, observation dates and source-provenance inputs. Positive persons and compatible area units only. No mapped-polygon equivalence inferred. Existing source qualifications and original input IDs retained. Computation produces a dated derived statistical density, not an official historical density measurement.'});
 return {claims:claims.length,slots:r.newSafeDensitySlots,mappedPairs:r.mappedPairsExplicitlyScopeCertified};
}
if(isCLI(import.meta.url))console.log(JSON.stringify(process.argv.includes('--1960')?assess1960():process.argv.includes('--build-density')?buildDensity():assessDensity()).slice(0,1800));
